const express = require('express');
const rateLimit = require('express-rate-limit');
const slowDown = require('express-slow-down');
const helmet = require('helmet');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Sets security headers
app.use(xss()); // Sanitizes user input
app.use(hpp()); // Prevents HTTP Parameter Pollution

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  }
});

// Apply rate limiter to all requests
app.use(limiter);

// Slow down requests after certain threshold
const speedLimiter = slowDown({
  windowMs: 15 * 60 * 1000,
  delayAfter: 50, // Allow 50 requests per 15 minutes, then slow down
  delayMs: 500 // Slow down subsequent responses by 500ms
});

app.use(speedLimiter);

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;

  // If id parameter exists, validate it
  if (id && (!Number.isInteger(Number(id)) || Number(id) <= 0)) {
    return res.status(400).json({
      error: 'Invalid ID parameter. ID must be a positive integer.'
    });
  }

  next();
};

app.get('/health', (req, res) => {
  // Basic health check with minimal information
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateIdParam, (req, res) => {
  // In a real application, this would query a database
  // Here we're returning static data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const error = {...err};
  error.message = err.message || 'Something went wrong!';

  // Handle specific error types
  if (err.name === 'CastError') {
    error.message = 'Resource not found';
    error.statusCode = 404;
  }

  // Add more error type handling as needed

  res.status(error.statusCode || 500).json({
    status: 'error',
    error: error.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

