/**
 * Security middleware for the application
 * Implements various security best practices
 */

// Basic security headers (lightweight alternative to helmet)
const securityHeaders = (req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Prevent page from being displayed in an iframe (clickjacking protection)
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS filter in browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Disable caching by default
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
};

// Input sanitization middleware (lightweight alternative to xss-clean)
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key]
          .replace(/<script[^>]*?>.*?<\/script>/gi, '')
          .replace(/<.*?>/g, '') // Strip all HTML tags
          .replace(/javascript:/gi, '')
          .replace(/vbscript:/gi, '')
          .replace(/on\w+=/gi, ''); // Remove event handlers
      }
    });
  }

  // Sanitize body parameters if present
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key]
          .replace(/<script[^>]*?>.*?<\/script>/gi, '')
          .replace(/<.*?>/g, '')
          .replace(/javascript:/gi, '')
          .replace(/vbscript:/gi, '')
          .replace(/on\w+=/gi, '');
      }
    });
  }

  next();
};

// HTTP Parameter Pollution protection (lightweight alternative)
const preventHPP = (req, res, next) => {
  // If any query parameter is an array, log and use only the first value
  Object.keys(req.query).forEach(key => {
    if (Array.isArray(req.query[key])) {
      console.warn(`HPP attempt detected: parameter ${key} has multiple values`);
      req.query[key] = req.query[key][0]; // Use only the first value
    }
  });

  // Same for body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (Array.isArray(req.body[key])) {
        console.warn(`HPP attempt detected in body: parameter ${key} has multiple values`);
        req.body[key] = req.body[key][0];
      }
    });
  }

  next();
};

// Rate limiting middleware (basic implementation)
const createRateLimiter = (options = {}) => {
  const windowMs = options.windowMs || 15 * 60 * 1000; // 15 minutes
  const maxRequests = options.max || 100;
  const message = options.message || 'Too many requests from this IP, please try again later.';

  // Simple in-memory store (for demo purposes)
  const requestStore = new Map();

  return (req, res, next) => {
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();
    const windowStart = now - windowMs;

    // Get or create record for this IP
    if (!requestStore.has(ip)) {
      requestStore.set(ip, []);
    }

    // Clean old requests outside the window
    const requests = requestStore.get(ip).filter(timestamp => timestamp > windowStart);
    requestStore.set(ip, requests);

    // Check if limit exceeded
    if (requests.length >= maxRequests) {
      return res.status(429).json({ 
        error: message,
        retryAfter: windowMs / 1000 // Suggest retry after window duration
      });
    }

    // Add current request timestamp
    requests.push(now);
    requestStore.set(ip, requests);

    next();
  };
};

module.exports = {
  securityHeaders,
  sanitizeInput,
  preventHPP,
  createRateLimiter
};

