  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({
  limit: '10kb'
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Input validation middleware for users endpoint
const validateUsersRequest = [
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('Page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    .toInt(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array()
      });
    }
    next();
  }
];

// Enhanced health endpoint with error handling
app.get('/health', [
  (req, res, next) => {
    try {
      // Validate query parameters if present
      if (req.query.verbose !== undefined && req.query.verbose !== 'true' && req.query.verbose !== 'false') {
        return res.status(400).json({
          status: 'error',
          message: 'Verbose parameter must be "true" or "false"'
        });
      }
      next();
    } catch (err) {
      next(err);
    }
  }
], (req, res) => {
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  };

  if (req.query.verbose === 'true') {
    healthData.process = {
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };
  }

  res.json(healthData);
});

// Enhanced users endpoint with validation and error handling
app.get('/users', validateUsersRequest, (req, res) => {
  try {
    // Simulated user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Evan', email: 'evan@example.com' }
    ];

    // Extract pagination parameters
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const offset = (page - 1) * limit;

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        pages: Math.ceil(allUsers.length / limit)
      }
    });
  } catch (error) {
    // This should not happen with proper validation, but just in case
    console.error('Error in users endpoint:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      message: 'Validation error',
      details: err.message
    });
  }

  // Fallback for all other errors
  res.status(500).json({
    status: 'error',
    message: 'Something went wrong!'
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

