const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.hidePoweredBy());

// Set request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error(err.stack);

  if (res.headersSent) {
    return next(err);
  }

  const errorResponse = {
    error: 'Internal Server Error',
    code: 'INTERNAL_ERROR',
    timestamp: new Date().toISOString()
  };

  // Add request ID for debugging in production
  if (process.env.NODE_ENV === 'production') {
    // Remove stack trace in production
    res.status(500).json(errorResponse);
  } else {
    // Include stack trace in development
    errorResponse.stack = err.stack;
    res.status(500).json(errorResponse);
  }
};

// Input validation middleware for users endpoint
const validateUsersParams = [
  (req, res, next) => {
    // Validate query parameters
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;

    // Set defaults and limits
    req.validatedQuery = {
      page: Math.max(1, page),
      limit: Math.min(100, Math.max(1, limit)) // Max 100 items per page
    };

    next();
  }
];

// Add health check with input validation
app.get('/health', [
  // Validate query parameters
  (req, res, next) => {
    const verbose = req.query.verbose === 'true';
    req.validatedQuery = { verbose };
    next();
  }
], (req, res) => {
  const healthData = {
    status: 'ok', 
    timestamp: new Date().toISOString()
  };

  // Add additional info if verbose
  if (req.validatedQuery.verbose) {
    healthData.nodeEnv = process.env.NODE_ENV || 'unknown';
    healthData.pid = process.pid;
  }

  res.json(healthData);
});

// Enhanced users endpoint with validation and error handling
app.get('/users', validateUsersParams, (req, res, next) => {
  try {
    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const { page, limit } = req.validatedQuery;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = {};

    if (endIndex < users.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.current_page = page;
    results.total_items = users.length;
    results.data = users.slice(startIndex, endIndex);

    res.json(results);
  } catch (error) {
    next(error);
  }
});

// Catch 404 errors
app.use('*', (req, res, next) => {
  const error = new Error(`Route ${req.method} ${req.url} not found`);
  error.status = 404;
  error.code = 'NOT_FOUND';
  next(error);
});

// Use error handling middleware
app.use(errorHandler);

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log('Security features enabled: Helmet, Rate Limiting, Input Validation');
});

// Close server gracefully
server.on('close', () => {
  console.log('Server closed');
});

module.exports = app;

