app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Request parsing with size limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Timeout for requests
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 second timeout
  next();
});

// Input validation middleware
const validateUserParams = (req, res, next) => {
  // Example validation - would expand based on actual needs
  if (req.query.page && (isNaN(req.query.page) || req.query.page < 1)) {
    return res.status(400).json({
      error: 'Invalid page parameter'
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  // Validate input parameters
  const allowedFields = ['detailed', 'format'];
  const invalidParams = Object.keys(req.query).filter(param => 
    !allowedFields.includes(param)
  );

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameters: ${invalidParams.join(', ')}`
    });
  }

  const healthData = {
    status: 'ok', 
    timestamp: new Date().toISOString()
  };

  if (req.query.detailed === 'true') {
    healthData.process = {
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };
  }

  res.json(healthData);
});

// Users endpoint with input validation
app.get('/users', validateUserParams, (req, res) => {
  try {
    // Simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate pagination if requested
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Basic pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = {};

    if (endIndex < users.length) {
      results.next = { page: page + 1, limit: limit };
    }

    if (startIndex > 0) {
      results.previous = { page: page - 1, limit: limit };
    }

    results.results = users.slice(startIndex, endIndex);
    results.total = users.length;

    res.json(results);
  } catch (error) {
    console.error('Error processing users request:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
