/**
 * Error handling middleware
 * Handles errors and sends structured responses
 */

/**
 * Handle errors and send structured response
 * @param {Error} err - Error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Next middleware function
 */
function errorHandler(err, req, res, next) {
  // Log the error (in production, use a proper logging service)
  console.error('Error:', err.message, {\n    stack: err.stack,\n    url: req.url,\n    method: req.method,\n    ip: req.ip,\n    userAgent: req.get('User-Agent')\n  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't leak stack traces in production
  const response = {\n    success: false,\n    message: process.env.NODE_ENV === 'production' \n      ? 'Internal server error' \n      : err.message,\n    timestamp: new Date().toISOString()\n  };

  // Add stack trace only in development
  if (process.env.NODE_ENV !== 'production' && err.stack) {\n    response.stack = err.stack;\n  }

  res.status(statusCode).json(response);
}

module.exports = errorHandler;

/**
 * Input validation middleware
 * Validates and sanitizes incoming requests
 */
const { body, query, param, validationResult } = require('express-validator');

/**
 * Validate user input for user-related operations
 */
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be 0 or positive')
    .toInt(),

  query('search')
    .optional()
    .isString()
    .trim()
    .escape()
    .isLength({ max: 100 })
    .withMessage('Search query too long')
];

/**
 * Check for validation errors
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Next middleware function
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const error = new Error('Validation failed');
    error.statusCode = 400;
    error.validationErrors = errors.array();
    return next(error);
  }
  next();
};

module.exports = {
  validateUserQuery,
  validate
};

/**
 * Structured logging utility
 */

class Logger {
  constructor() {
    this.level = process.env.LOG_LEVEL || 'info';
    this.levels = {
      'debug': 0,
      'info': 1, 
      'warn': 2,
      'error': 3
    };
  }

  /**
   * Log message at debug level
   * @param {string} message - Message to log
   * @param {Object} context - Additional context
   */
  debug(message, context = {}) {
    if (this.levels[this.level] <= 0) {
      this._log('DEBUG', message, context);
    }
  }

  /**
   * Log message at info level
   * @param {string} message - Message to log
   * @param {Object} context - Additional context
   */
  info(message, context = {}) {
    if (this.levels[this.level] <= 1) {
      this._log('INFO', message, context);
    }
  }

  /**
   * Log message at warning level
   * @param {string} message - Message to log
   * @param {Object} context - Additional context
   */
  warn(message, context = {}) {
    if (this.levels[this.level] <= 2) {
      this._log('WARN', message, context);
    }
  }

  /**
   * Log message at error level
   * @param {string} message - Message to log
   * @param {Object} context - Additional context
   */
  error(message, context = {}) {
    if (this.levels[this.level] <= 3) {
      this._log('ERROR', message, context);
    }
  }

  /**
   * Internal method to format and output log
   * @private
   */
  _log(level, message, context) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      ...context
    };
    console.log(JSON.stringify(logEntry));
  }
}

module.exports = new Logger();

