const logger = require('./utils/logger');

// Rate limiting (basic implementation)
const rateLimit = {};
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const RATE_LIMIT_COUNT = 100; // 100 requests per minute

const checkRateLimit = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean old entries
  Object.keys(rateLimit).forEach(key => {
    if (rateLimit[key].timestamp < now - RATE_LIMIT_WINDOW) {
      delete rateLimit[key];
    }
  });

  if (!rateLimit[ip]) {
    rateLimit[ip] = { count: 1, timestamp: now };
  } else {
    rateLimit[ip].count++;
  }

  if (rateLimit[ip].count > RATE_LIMIT_COUNT) {
    logger.warn('Rate limit exceeded', { ip, count: rateLimit[ip].count });
    const error = new Error('Rate limit exceeded. Try again later.');
    error.statusCode = 429;
    return next(error);
  }

  next();
};

// Apply rate limiting to all routes
