const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// CORS configuration - restrict to known origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://your-trusted-domain.com'] 
    : '*', // Allow all in development
  credentials: true,
};
app.use(cors(corsOptions));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// Body parsing with size limits to prevent denial of service
app.use(express.json({ 
  limit: '10kb',
  type: ['application/json']
}));

// Input validation middleware for any routes that need it
const validateUserQuery = [
  (req, res, next) => {
    // Validate query parameters if present
    if (req.query.limit && (isNaN(req.query.limit) || parseInt(req.query.limit) <= 0 || parseInt(req.query.limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a number between 1 and 100.'
      });
    }

    if (req.query.page && (isNaN(req.query.page) || parseInt(req.query.page) <= 0)) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive number.'
      });
    }

    next();
  }
];

// Health check endpoint with minimal info
app.get('/health', (req, res) => {
  // Consider not exposing timestamp or other potentially useful info to attackers
  res.json({ status: 'ok' });
});

// Users endpoint with input validation and error handling
app.get('/users', validateUserQuery, (req, res) => {
  try {
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination example (though data is static in this demo)
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const startIndex = (page - 1) * limit;

    // Simulate pagination on our static data
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    console.error('Error processing users request:', error);
