  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "helmet": "^7.0.0",
    "express-validator": "^7.0.1",
    "dotenv": "^16.0.3"
  }
}

/**
 * Centralized error handling middleware
 * Follows security best practices for error disclosure
 */

// Security: Never expose internal error details to clients
const errorHandler = (err, req, res, next) => {
  // Log full error details internally (would use proper logging in production)
  console.error('Error details:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    headers: req.headers
  });

  // Security: Generic error response to prevent information disclosure
  const status = err.status || 500;
  const isProd = process.env.NODE_ENV === 'production';

  res.status(status).json({
    error: {
      message: isProd && status === 500 
        ? 'Internal server error' 
        : err.message,
      status: status
    }
  });
};

module.exports = errorHandler;

/**
 * Input validation utilities
 * Implements security best practices for input validation
 */

const { body, param, validationResult } = require('express-validator');

/**
 * Validate user input for user operations
 * Implements whitelist validation approach
 */
const userValidationRules = () => [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must be a valid email address')
];

/**
 * Validate ID parameters
 */
const idValidationRule = (paramName = 'id') => [
  param(paramName)
    .isInt({ min: 1 })
    .withMessage(`${paramName} must be a positive integer`)
];

/**
 * Generic validation result handler
 */
const validate = (req, res, next) => {
  try {
    const errors = validationResult(req);

    if (!errors.isEmpty()) {
      // Security: Standardized error format to prevent information leakage
      return res.status(400).json({
        error: {
          message: 'Validation failed',
          details: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        }
      });
    }

    next();
  } catch (err) {
    next(err);
  }
};

module.exports = {
  userValidationRules,
  idValidationRule,
  validate
};

/**
 * Security middleware implementation
 * Addresses common web application vulnerabilities
 */

const helmet = require('helmet');

/**
 * Security headers middleware
 * Uses Helmet to set various HTTP security headers
 */
const securityHeaders = helmet({
  // Prevent clickjacking attacks
  frameguard: {
    action: 'deny'
  },

  // Enable XSS protection
  xssFilter: true,

  // Prevent sniffing of MIME types
  nosniff: true,

  // Hide powered-by header to reduce information disclosure
  hidePoweredBy: {
    setTo: 'PHP/5.3.3'
  },

  // Strict transport security (enable in production with HTTPS)
  hsts: {
    maxAge: 31536000, // 1 year
